import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"篇881｜超脱者与政治·超脱者的政治中立原则","description":"","frontmatter":{"title":"篇881｜超脱者与政治·超脱者的政治中立原则","no":881,"module":4,"tags":["超脱","政治","政治中立","不结盟","万族共和"],"related":["0049-治理框架与权力制衡","880-超脱者的政治参与边界","792-伦理-不干涉原则","789-法律约束与豁免边界"]},"headers":[],"relativePath":"zh/0881_模块4-超脱者与政治-政治中立原则.md","filePath":"zh/0881_模块4-超脱者与政治-政治中立原则.md"}'),l={name:"zh/0881_模块4-超脱者与政治-政治中立原则.md"};function i(h,a,n,s,u,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="篇881-超脱者与政治·超脱者的政治中立原则" tabindex="-1">篇881｜超脱者与政治·超脱者的政治中立原则 <a class="header-anchor" href="#篇881-超脱者与政治·超脱者的政治中立原则" aria-label="Permalink to &quot;篇881｜超脱者与政治·超脱者的政治中立原则&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档49、880、792、789</p></blockquote><h2 id="引言-超脱者不站队——因为他的力量站任何一边都会压垮天平" tabindex="-1">引言：超脱者不站队——因为他的力量站任何一边都会压垮天平 <a class="header-anchor" href="#引言-超脱者不站队——因为他的力量站任何一边都会压垮天平" aria-label="Permalink to &quot;引言：超脱者不站队——因为他的力量站任何一边都会压垮天平&quot;">​</a></h2><p>旧世界的强者天然站队。他和这个宗门关系好，就帮这个宗门打那个宗门；他看上了某个王朝，就扶持它统一天下。他的力量像一杆秤上的砝码——放哪一边，哪边就赢。衡元宙必须把这个砝码从秤上拿下来：<strong>超脱者在万族政治中必须保持中立，不站队、不偏帮、不选边。</strong> 本篇讲这条中立原则。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求中立是为了不助纣为虐；万族共和公理要求超脱者对万族一切族群一视同仁；集体升维公理要求中立服务于整体升维而非局部利益；因果自律公理要求中立行为可追溯；法则优先公理要求中立原则法则级自洽；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、为什么超脱者必须中立" tabindex="-1">一、为什么超脱者必须中立 <a class="header-anchor" href="#一、为什么超脱者必须中立" aria-label="Permalink to &quot;一、为什么超脱者必须中立&quot;">​</a></h2><p>超脱者的中立不是道德选择，是物理必需：</p><ul><li><strong>他太重了</strong>：一个超脱者的力量足以影响任何政治斗争的结果。他站哪边，哪边就赢——这不是公平竞争，这是力量碾压</li><li><strong>他太久了</strong>：超脱者活几万年，他今天站的这个政治力量，明天可能就变成了新的压迫者。长期站队必然异化</li><li><strong>他太广了</strong>：超脱者同时面对无数族群、无数位面、无数议题。他不可能在每个议题上都有立场——如果硬要有，他的立场会自相矛盾</li><li><strong>他是公共资源</strong>：超脱者是万族共建的公共资源，不是任何政治派别的私器</li></ul><p>四个理由合起来：<strong>超脱者站队的代价太大，大到万族承担不起。</strong></p><h2 id="二、中立原则的三层含义" tabindex="-1">二、中立原则的三层含义 <a class="header-anchor" href="#二、中立原则的三层含义" aria-label="Permalink to &quot;二、中立原则的三层含义&quot;">​</a></h2><h3 id="第一层-不偏帮" tabindex="-1">第一层：不偏帮 <a class="header-anchor" href="#第一层-不偏帮" aria-label="Permalink to &quot;第一层：不偏帮&quot;">​</a></h3><p>超脱者不在万族内部的政治斗争中选边。两个族群因为资源分配吵架，超脱者不帮任何一方——他提供技术数据，但不替任何一方站队。</p><h3 id="第二层-不裁决" tabindex="-1">第二层：不裁决 <a class="header-anchor" href="#第二层-不裁决" aria-label="Permalink to &quot;第二层：不裁决&quot;">​</a></h3><p>超脱者不充当万族内部政治纠纷的&quot;终审法官&quot;。纠纷由议事会协商、由共生法院裁决，超脱者不越俎代庖。</p><h3 id="第三层-不偏好" tabindex="-1">第三层：不偏好 <a class="header-anchor" href="#第三层-不偏好" aria-label="Permalink to &quot;第三层：不偏好&quot;">​</a></h3><p>超脱者在资源分配、岗位安排、晋升评审中不表现出对特定族群、区域、师承的偏好。阿赖耶网络+多层监督会检测分配数据中的系统性偏差。</p><p>三层合起来：<strong>中立不是冷漠，是公平。</strong> 超脱者对万族的爱，不偏向其中任何一个孩子。</p><h2 id="三、中立的例外-什么情况下可以不中立" tabindex="-1">三、中立的例外：什么情况下可以不中立 <a class="header-anchor" href="#三、中立的例外-什么情况下可以不中立" aria-label="Permalink to &quot;三、中立的例外：什么情况下可以不中立&quot;">​</a></h2><p>中立原则不是绝对的。在两种情况下，超脱者可以打破中立：</p><h3 id="例外一-掠夺派入侵" tabindex="-1">例外一：掠夺派入侵 <a class="header-anchor" href="#例外一-掠夺派入侵" aria-label="Permalink to &quot;例外一：掠夺派入侵&quot;">​</a></h3><p>如果外部掠夺派势力入侵万族共和领土，超脱者必须全力抵抗——这不是站队，这是自卫。中立不适用于生死存亡的外部威胁。</p><h3 id="例外二-万族内部出现掠夺行为" tabindex="-1">例外二：万族内部出现掠夺行为 <a class="header-anchor" href="#例外二-万族内部出现掠夺行为" aria-label="Permalink to &quot;例外二：万族内部出现掠夺行为&quot;">​</a></h3><p>如果万族内部某个群体正在掠夺其他群体（比如某个大族欺压小族），超脱者必须制止。这不是站队，这是执法——反掠夺主义公理高于中立原则。</p><p>两个例外的共同点：<strong>中立保护的是万族共和内部的公平竞争，不是保护掠夺者的&quot;权利&quot;。</strong> 当中立本身变成对掠夺的纵容时，中立就让位于反掠夺。</p><h2 id="四、中立与技术意见的区别" tabindex="-1">四、中立与技术意见的区别 <a class="header-anchor" href="#四、中立与技术意见的区别" aria-label="Permalink to &quot;四、中立与技术意见的区别&quot;">​</a></h2><p>保持中立不等于不能发表技术意见。超脱者可以说：</p><ul><li>&quot;这个方案在法则层面有X风险&quot;</li><li>&quot;那个方案的因果扰动范围是Y&quot;</li><li>&quot;根据阿赖耶数据，Z方案的长期效果更好&quot;</li></ul><p>这些是技术事实陈述，不是政治立场。区别在于：</p><ul><li>技术陈述：&quot;这条路在法则上走不通&quot;——中立</li><li>政治立场：&quot;我支持这条路，因为它对我朋友好&quot;——不中立</li></ul><p>超脱者只做前者，不做后者。</p><p>中立不是冷漠。超脱者对万族的爱，体现在他把全部精力放在岗位履职上——维护法则网络、引导万族进化、开拓新位面。这些工作本身就是对万族最大的爱。他不需要在政治斗争中选边来证明自己爱谁——他修的每一段法则、教的每一堂课，都是爱。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：不把超脱者的力量浪费在万族内部政治斗争中</li><li><strong>反掠夺</strong>：中立防止超脱者变成某一方的掠夺工具</li><li><strong>唐罗上限对比</strong>：唐罗的&quot;中立&quot;其实是选择性恩赐——他想帮谁就帮谁；衡元宙的中立是制度性的，不因人因事而偏</li><li><strong>万族全覆盖</strong>：中立意味着对五大谱系一视同仁</li><li><strong>超多元全开放</strong>：中立原则执行记录、例外触发案例全部通过无私道全网开放</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者的政治中立，不是冷漠，是公平。他不站队、不偏帮、不裁决、不偏好；他提供技术事实，不发表政治立场。唯一的例外是外部掠夺入侵和内部掠夺行为——那时中立让位于自卫和执法。当最强的人不站队，万族才能自己决定自己的命运。这，才是超脱者政治中立原则的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0049-治理框架与权力制衡.html">0049-治理框架与权力制衡</a> · <a href="./0880_模块4-超脱者与政治-政治参与边界.html">880-超脱者的政治参与边界</a> · <a href="./0792_模块4-伦理-不干涉原则.html">792-伦理-不干涉原则</a> · <a href="./0789_模块4-制度-法律约束与豁免边界.html">789-法律约束与豁免边界</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',38)])])}const _=t(l,[["render",i]]);export{q as __pageData,_ as default};
